select cust_id,cust_first_name,cust_last_name,cust_gender from sh.customers where cust_gender = 'F';
select cust_id,cust_first_name,cust_last_name,cust_year_of_birth from sh.customers where cust_last_name like '%s' and cust_year_of_birth > 1970;
select prod_id,prod_name,prod_category,prod_list_price from sh.products where prod_list_price between 100 and 500;
select prod_id,prod_name,prod_min_price,prod_status from sh.products where min_price < 50 and prod_status = "available";
select prod_id,cust_id,quantity_sold,amount_sold from sh.sales where amount_sold > 1000;
select * from sh.sales where quantity_sold > 2 and channel_id = 3;
select channel_id,channel_desc from sh.channels where channel_desc like '%Direct%';
select promo_id,promo_name,promo_cost,promo_category from sh.promotions where promo_cost > 1000;
select promo_id,promo_name,promo_begin_date,promo_end_date,promo_cost from sh.promotions where promo_end_date > promo_begin_date and promo_cost > 500;
select time_day,day_name,calender_month,calendar_year from sh.times where calendar_year = 2000;
select * from sh.times where calendar_month_name = 'December' and calendar_year = 2001;
select prod_id,time_id,unit_cost,unit_price from sh.costs where unit_price > unit_cost;
select * from sh.costs where unit_cost > 100 and unit_price < 1000;
select cust_id,education,occupation,household_size from supplementary_demographics where household_size > 3;
select maritial_status,count(*) as cust_count from sh.customers group by maritial_status;
select cust_gender,AVG(year_of_birth) as avg_year_of_birth from sh.customers GROUP BY cust_gender;
select prod_category,AVG(prod_list_price) AS prod_avg_list_price from sh.products GROUP BY category;
select subcategory,MAX(min_price) As prod_highest_min_price from sh.products GROUP BY subcategory;
select channel_id,SUM(amount_sold) AS total_sales from sh.sales GROUP BY channel_id;
select prod_id,SUM(quamtity_sold) As total_quantity from sh.sales GROUP BY prod_id;
select promo_id,AVG(amount_sold) AS average_sales from sh.sales GROUP BY promo_id;
select promo_category,SUM(promo_cost) AS total_promo_cost from sh.promotions GROUP BY promo_category;
select region_id,count(*) AS country_count from sh.countries GROUP BY region_id;
select prod_id,AVG(unit_cost) As average_unit_coat from sh.costs GROUP BY prod_id;
select gender,maritial_status,count(*) AS customer_count from sh.customers GROUP BY gender,maritial_status;
select prod_category,prod_subcategory,count(*) AS prod_count from sh.products GROUP BY sh.category,sh.subcategory;
select prod_id,channel_id,SUM(amount_sold) AS total_sales from sh.sales GROUP BY prod_id,channel_id;
select channel_id,promo_id,SUM(quantity_sold) AS total_quantity from sh.sales GROUP BY channel_id,promo_id;
select prod_id, promo_id, AVG(unit_cost) AS average_unit_cost FROM sh.costs GROUP BY prod_id, promo_id;
SELECT channel_id,SUM(amount_sold) AS total_sales_amount FROM sh.sales WHERE amount_sold > 500 GROUP BY channel_id;
SELECT category, AVG(list_price) AS average_list_price FROM sh.products WHERE list_price > 100 GROUP BY category;
SELECT marital_status,COUNT(*) AS customer_count FROM sh.customers WHERE year_of_birth > 1970 GROUP BY marital_status;
SELECT promo_category, AVG(promo_cost) AS average_promo_cost FROM sh.promotions WHERE promo_cost > 500 GROUP BY promo_category;
SELECT product_id, MAX(unit_price) AS maximum_unit_price FROM sh.costs WHERE unit_cost > 50 GROUP BY product_id;
SELECT marital_status, COUNT(*) AS customer_count FROM sh.customers GROUP BY marital_status HAVING COUNT(*) > 100;
SELECT category, AVG(list_price) AS average_list_price FROM sh.products GROUP BY category HAVING AVG(list_price) > 500;
SELECT channel_id, SUM(amount_sold) AS total_sales_amount FROM sh.sales GROUP BY channel_id HAVING SUM(amount_sold) > 100000;
SELECT promo_category, AVG(promo_cost) AS average_promo_cost FROM sh.promotions GROUP BY promo_category HAVING AVG(promo_cost) > 1000;
SELECT product_id, AVG(unit_price) AS average_unit_price FROM sh.costs GROUP BY product_id HAVING AVG(unit_price) > 500;